import { toggleNotificationPreference, getNotificationPreference } from './actions';

export default async function Home() {
  // For demo purposes, using a hardcoded userId
  const userId = 'user-123';
  const notificationEnabled = await getNotificationPreference(userId);

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Settings</h1>

      <div style={{ marginTop: '1.5rem' }}>
        <h2>Notification Preferences</h2>
        <p>
          Notifications are currently: <strong>{notificationEnabled ? 'ON' : 'OFF'}</strong>
        </p>

        <form action={toggleNotificationPreference.bind(null, userId)}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              fontSize: '1rem',
              cursor: 'pointer',
              backgroundColor: notificationEnabled ? '#dc2626' : '#16a34a',
              color: 'white',
              border: 'none',
              borderRadius: '0.375rem',
            }}
          >
            Turn {notificationEnabled ? 'Off' : 'On'}
          </button>
        </form>

        <p style={{ marginTop: '1rem', fontSize: '0.875rem', color: '#666' }}>
          Click the button to toggle your notification preference.
          The page will refresh automatically to show the updated state.
        </p>
      </div>
    </main>
  );
}

